319	/// Resolve `request_target` (HTTP request path, e.g. `/foo/bar?x=1`) to a file under `site_canon`.
320	/// Returns `ResolveResult::File` for success, `Redirect` if a trailing slash is needed for a directory,
321	/// or `NotFound` for traversal attempts or missing files.
322	///
323	/// NOTE: This function preserves and hardens the multi-layer security from PR#18:
324	/// 1. Percent-decoding via `percent_decode_path`.
325	/// 2. Null byte rejection.
326	/// 3. Traversal blocking (`..`).
327	/// 4. Symlink escape prevention via canonicalization and prefix checking.
328	fn resolve_site_file(site_canon: &Path, request_target: &str) -> ResolveResult {
329	    let path_only = match request_target
330	        .split('?')
331	        .next()
332	        .and_then(|s| s.split('#').next())
333	    {
334	        Some(p) => p,
335	        None => return ResolveResult::NotFound,
336	    };
337	
338	    // [Security] Handle percent-encoding and reject null bytes (from PR#18)
339	    let decoded = percent_decode_path(path_only);
340	    if decoded.as_bytes().contains(&0) {
341	        return ResolveResult::NotFound;
342	    }
343	
344	    let rel = decoded.trim_start_matches('/');
345	    let mut file_path = site_canon.to_path_buf();
346	    if !rel.is_empty() {
347	        for seg in rel.split('/').filter(|s| !s.is_empty()) {
348	            // [Security] Block directory traversal (from PR#18)
349	            if seg == ".." {
350	                return ResolveResult::NotFound;
351	            }
352	            file_path.push(seg);
353	        }
354	    }
355	
356	    if file_path.is_dir() {
357	        // If it refers to a directory but lacks a trailing slash, redirect so relative links work.
358	        if !request_target.ends_with('/') && !request_target.is_empty() {
359	            return ResolveResult::Redirect(format!("{path_only}/"));
360	        }
361	        file_path.push("index.html");
362	    }
363	
364	    // [Security] Canonicalize and verify we're still within site_canon (from PR#18)
365	    let real = match fs::canonicalize(&file_path) {
366	        Ok(r) => r,
367	        Err(_) => return ResolveResult::NotFound,
368	    };
369	
370	    if !real.starts_with(site_canon) || !real.is_file() {
371	        return ResolveResult::NotFound;
372	    }
373	
374	    ResolveResult::File(real)
375	}
