377	fn hex_val(c: u8) -> Option<u8> {
378	    match c {
379	        b'0'..=b'9' => Some(c - b'0'),
380	        b'a'..=b'f' => Some(c - b'a' + 10),
381	        b'A'..=b'F' => Some(c - b'A' + 10),
382	        _ => None,
383	    }
384	}
385	
386	fn percent_decode_path(input: &str) -> String {
387	    let mut decoded = Vec::with_capacity(input.len());
388	    let b = input.as_bytes();
389	    let mut i = 0;
390	    while i < b.len() {
391	        if b[i] == b'%' && i + 2 < b.len() {
392	            if let (Some(hi), Some(lo)) = (hex_val(b[i + 1]), hex_val(b[i + 2])) {
393	                decoded.push(hi << 4 | lo);
394	                i += 3;
395	                continue;
396	            }
397	        }
398	        decoded.push(b[i]);
399	        i += 1;
400	    }
401	    String::from_utf8_lossy(&decoded).into_owned()
402	}
