406	fn cmd_serve() {
407	    let site = project_root().join("site");
408	    let site_canon = fs::canonicalize(&site).expect(
409	        "site/ not found — run `cargo xtask build` first (e.g. `cargo xtask serve` runs build automatically)",
410	    );
411	    let addr = "127.0.0.1:3000";
412	    let listener = TcpListener::bind(addr).expect("failed to bind port 3000");
413	
414	    // Handle Ctrl+C gracefully so cargo doesn't report an error
415	    ctrlc_exit();
416	
417	    println!("\nServing at http://localhost:3000  (Ctrl+C to stop)");
418	
419	    for stream in listener.incoming() {
420	        let Ok(mut stream) = stream else { continue };
421	        let mut buf = [0u8; 4096];
422	        let n = stream.read(&mut buf).unwrap_or(0);
423	        let request = String::from_utf8_lossy(&buf[..n]);
424	
425	        let path = request
426	            .lines()
427	            .next()
428	            .and_then(|line| line.split_whitespace().nth(1))
429	            .unwrap_or("/");
430	
431	        match resolve_site_file(&site_canon, path) {
432	            ResolveResult::File(file_path) => {
433	                let body = fs::read(&file_path).unwrap_or_default();
434	                let mime = guess_mime(&file_path);
435	                let header = format!(
436	                    "HTTP/1.1 200 OK\r\nContent-Type: {mime}\r\nContent-Length: {}\r\n\r\n",
437	                    body.len()
438	                );
439	                let _ = stream.write_all(header.as_bytes());
440	                let _ = stream.write_all(&body);
441	            }
442	            ResolveResult::Redirect(new_path) => {
443	                let header = format!(
444	                    "HTTP/1.1 301 Moved Permanently\r\nLocation: {new_path}\r\nContent-Length: 0\r\n\r\n"
445	                );
446	                let _ = stream.write_all(header.as_bytes());
447	            }
448	            ResolveResult::NotFound => {
449	                let body = b"404 Not Found";
450	                let header = format!(
451	                    "HTTP/1.1 404 Not Found\r\nContent-Length: {}\r\n\r\n",
452	                    body.len()
453	                );
454	                let _ = stream.write_all(header.as_bytes());
455	                let _ = stream.write_all(body);
456	            }
457	        }
458	    }
459	}
