461	/// Install a Ctrl+C handler that exits cleanly (code 0) instead of
462	/// letting the OS terminate with STATUS_CONTROL_C_EXIT.
463	fn ctrlc_exit() {
464	    ctrlc::set_handler(move || {
465	        std::process::exit(0);
466	    })
467	    .expect("Error setting Ctrl-C handler");
468	}
