470	fn guess_mime(path: &Path) -> &'static str {
471	    match path.extension().and_then(|e| e.to_str()) {
472	        Some("html") => "text/html; charset=utf-8",
473	        Some("css") => "text/css",
474	        Some("js") => "application/javascript",
475	        Some("svg") => "image/svg+xml",
476	        Some("png") => "image/png",
477	        Some("jpg" | "jpeg") => "image/jpeg",
478	        Some("woff2") => "font/woff2",
479	        Some("woff") => "font/woff",
480	        Some("json") => "application/json",
481	        _ => "application/octet-stream",
482	    }
483	}
